CREATE TABLE app_user (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, farm_name VARCHAR(120) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'OWNER');
CREATE TABLE supply (id UUID PRIMARY KEY, farm_id UUID NOT NULL REFERENCES app_user(id), name VARCHAR(180) NOT NULL, category VARCHAR(80) NOT NULL, unit VARCHAR(30) NOT NULL, quantity NUMERIC(16,3) NOT NULL DEFAULT 0, minimum_stock NUMERIC(16,3) NOT NULL DEFAULT 0, supplier VARCHAR(180), location VARCHAR(180), unit_cost NUMERIC(16,4), archived BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT NOW(), version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_supply_farm ON supply(farm_id);
CREATE TABLE stock_movement (id UUID PRIMARY KEY, farm_id UUID NOT NULL REFERENCES app_user(id), supply_id UUID NOT NULL REFERENCES supply(id), supply_name VARCHAR(180) NOT NULL, type VARCHAR(20) NOT NULL, quantity NUMERIC(16,3) NOT NULL, unit VARCHAR(30) NOT NULL, movement_date DATE NOT NULL, counterparty VARCHAR(180), responsible VARCHAR(180), notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX idx_movement_supply ON stock_movement(supply_id); CREATE INDEX idx_movement_farm_date ON stock_movement(farm_id,movement_date DESC);
CREATE TABLE stock_alert (id UUID PRIMARY KEY, farm_id UUID NOT NULL REFERENCES app_user(id), supply_id UUID NOT NULL REFERENCES supply(id), supply_name VARCHAR(180) NOT NULL, type VARCHAR(80) NOT NULL, priority VARCHAR(20) NOT NULL, explanation VARCHAR(1200) NOT NULL, recommendation VARCHAR(1200) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'NOVO', analyzed_at TIMESTAMP NOT NULL DEFAULT NOW()); CREATE INDEX idx_alert_farm ON stock_alert(farm_id,analyzed_at DESC);
